#define DMX_GRAPH_NO_MAIN
#include "dmx_graph.cpp"
#include "reference_owned_dmx_projection.h"
#include <iostream>
int main(int argc,char**argv){try{static_assert(sizeof(void*)==8,"x64 required");if(argc!=3)throw std::runtime_error("input and fresh output required");auto original=loadGraph(argv[1]);auto expected=original;RecoveredOwnedDmxReferenceProjectionCandidate<Graph> p(original,[](const std::string&,auto&)->uint32_t{throw std::runtime_error("external input");});size_t models=0,writes=0;
 for(uint32_t i=0;i<original.elements.size();++i){const auto&e=original.elements[i];if(original.strings.at(e.type)!="DmeGameModel")continue;for(size_t j=0;j<e.attributes.size();++j){const auto&a=e.attributes[j];if(original.strings.at(a.name)!="flexWeights"||a.type!=17)continue;++models;for(size_t k=0;k<a.values.size();++k){uint32_t old=wireU32(a.values[k]);uint32_t incoming=old==0x3f000000?0xbf000000:0x3f000000;std::memcpy(expected.elements[i].attributes[j].values[k].wire.data(),&incoming,4);if(!p.setFloatArrayElement(i,"flexWeights",int32_t(k),incoming,0))throw std::runtime_error("fixture weight rejected");if(p.setFloatArrayElement(i,"flexWeights",int32_t(k),incoming,0))throw std::runtime_error("equal repeated write");++writes;}}}
 if(!models||!writes)throw std::runtime_error("no model weights exercised");auto edited=p.exportReferences([](uint32_t,const auto&)->std::string{throw std::runtime_error("external output");});saveGraph(edited,argv[2]);auto loaded=loadGraph(argv[2]);validateGraph(loaded);
 if(loaded.header!=expected.header||loaded.strings!=expected.strings||loaded.elements.size()!=expected.elements.size())throw std::runtime_error("graph metadata");
 for(size_t i=0;i<expected.elements.size();++i){const auto&a=expected.elements[i];const auto&b=loaded.elements[i];if(a.id!=b.id||a.type!=b.type||a.name!=b.name||a.attributes.size()!=b.attributes.size())throw std::runtime_error("element mismatch");for(size_t j=0;j<a.attributes.size();++j){const auto&x=a.attributes[j];const auto&y=b.attributes[j];if(x.name!=y.name||x.type!=y.type||x.values.size()!=y.values.size())throw std::runtime_error("attribute mismatch");for(size_t k=0;k<x.values.size();++k){const auto&v=x.values[k];const auto&w=y.values[k];if(v.wire!=w.wire||v.text!=w.text||v.reference!=w.reference||v.stringIndex!=w.stringIndex)throw std::runtime_error("value mismatch");}}}
 auto dirty=p.scene.queues.dirty.handles.size();p.scene.cleanup({},[](auto&,bool){},[](auto&){});if(p.scene.size()||p.scene.attributes.size()||p.scene.references.nodes.allocationCount())throw std::runtime_error("teardown");std::cout<<"models="<<models<<" weight_writes="<<writes<<" dirty_owners="<<dirty<<" complete_graph_save_reload=passed teardown=passed\n";return 0;
 }catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
